-- Inventions and discoveries. { answer, unit, en_q, en_fact, fr_q, fr_fact, source }
-- Append only: the position in this list is the question's id.
return {
    { 1450, "year", "Around which year did Gutenberg start printing with movable metal type in Mainz?", "Around 1450; his Bible followed a few years later.", "Vers quelle année Gutenberg a-t-il commencé à imprimer avec des caractères mobiles à Mayence ?", "Vers 1450 ; sa Bible suit quelques années plus tard.", "src: Johannes Gutenberg (c. 1450)" },
    { 1608, "year", "In which year was the first telescope patent filed, in the Netherlands?", "In 1608, by the spectacle-maker Hans Lippershey.", "En quelle année le premier brevet de lunette a-t-il été déposé, aux Pays-Bas ?", "En 1608, par le lunetier Hans Lippershey.", "src: History of the telescope" },
    { 1609, "year", "In which year did Galileo first turn a telescope to the sky?", "In 1609; he soon spotted four moons of Jupiter.", "En quelle année Galilée a-t-il braqué pour la première fois une lunette vers le ciel ?", "En 1609 ; il découvre bientôt quatre lunes de Jupiter.", "src: Galileo Galilei" },
    { 1769, "year", "In which year did James Watt patent his improved steam engine?", "In 1769 — the watt, the unit of power, is named after him.", "En quelle année James Watt a-t-il breveté sa machine à vapeur améliorée ?", "En 1769 — le watt, unité de puissance, porte son nom.", "src: James Watt (patent 1769)" },
    { 1800, "year", "In which year did Alessandro Volta build the first electric battery?", "In 1800 — hence the volt.", "En quelle année Alessandro Volta a-t-il construit la première pile électrique ?", "En 1800 — d'où le volt.", "src: Voltaic pile" },
    { 1844, "year", "In which year did Samuel Morse send his famous telegraph message 'What hath God wrought'?", "In May 1844, from Washington to Baltimore.", "En quelle année Samuel Morse a-t-il envoyé son célèbre télégramme « What hath God wrought » ?", "En mai 1844, de Washington à Baltimore.", "src: Morse telegraph (1844)" },
    { 1877, "year", "In which year did Thomas Edison invent the phonograph?", "In 1877; the first words recorded were 'Mary had a little lamb'.", "En quelle année Thomas Edison a-t-il inventé le phonographe ?", "En 1877 ; les premiers mots enregistrés : « Mary had a little lamb ».", "src: Phonograph" },
    { 1901, "year", "In which year did Marconi send the first radio signal across the Atlantic?", "In December 1901: the letter S in Morse code.", "En quelle année Marconi a-t-il envoyé le premier signal radio à travers l'Atlantique ?", "En décembre 1901 : la lettre S en morse.", "src: Guglielmo Marconi" },
    { 1926, "year", "In which year did John Logie Baird first demonstrate television in public?", "In January 1926, in London.", "En quelle année John Logie Baird a-t-il fait la première démonstration publique de la télévision ?", "En janvier 1926, à Londres.", "src: John Logie Baird" },
    { 1938, "year", "In which year did László Bíró patent his ballpoint pen?", "In 1938; in Argentina a ballpoint is still called a 'birome'.", "En quelle année László Bíró a-t-il breveté son stylo à bille ?", "En 1938 ; en Argentine, le stylo s'appelle encore « birome ».", "src: Ballpoint pen (Bíró patent 1938)" },
    { 1817, "year", "In which year did Karl Drais ride his 'running machine', the ancestor of the bicycle?", "In 1817 — it had no pedals.", "En quelle année Karl Drais a-t-il roulé sur sa « draisienne », l'ancêtre du vélo ?", "En 1817 — elle n'avait pas de pédales.", "src: Dandy horse (Drais 1817)" },
    { 6, "n", "How many raised dots make up a full Braille cell?", "Six, in two columns of three.", "Combien de points en relief compte une cellule braille complète ?", "Six, en deux colonnes de trois.", "src: Braille" },
    { 15, "age", "How old was Louis Braille when he devised his reading system?", "About 15, in 1824; he was blind from the age of five.", "Quel âge avait Louis Braille quand il a conçu son système d'écriture ?", "Environ 15 ans, en 1824 ; il était aveugle depuis l'âge de cinq ans.", "src: Louis Braille; web-checked" },
    { 1816, "year", "In which year did René Laennec invent the stethoscope?", "In 1816 — at first a simple rolled-up tube of paper.", "En quelle année René Laennec a-t-il inventé le stéthoscope ?", "En 1816 — d'abord un simple rouleau de papier.", "src: Stethoscope (Laennec)" },
    { 1867, "year", "In which year did Alfred Nobel patent dynamite?", "In 1867; his fortune later funded the Nobel Prizes.", "En quelle année Alfred Nobel a-t-il breveté la dynamite ?", "En 1867 ; sa fortune financera les prix Nobel.", "src: Dynamite" },
    { 1854, "year", "In which year did Elisha Otis demonstrate his safety lift by cutting its rope?", "In 1854, in New York — skyscrapers became possible.", "En quelle année Elisha Otis a-t-il présenté son ascenseur de sécurité en coupant le câble ?", "En 1854, à New York — les gratte-ciel devenaient possibles.", "src: Elisha Otis (1854 demonstration)" },
    { 1873, "year", "In which year did Levi Strauss and Jacob Davis patent riveted denim trousers?", "In 1873: the birth of jeans.", "En quelle année Levi Strauss et Jacob Davis ont-ils breveté le pantalon en toile renforcé de rivets ?", "En 1873 : la naissance du jean.", "src: Jeans (US patent 139,121)" },
    { 1955, "year", "In which year did George de Mestral patent the hook-and-loop fastener?", "In 1955, inspired by burrs stuck to his dog.", "En quelle année George de Mestral a-t-il breveté la fermeture auto-agrippante ?", "En 1955, inspiré par les fruits de bardane accrochés à son chien.", "src: Hook-and-loop fastener" },
    { 1945, "year", "In which year did Percy Spencer file the patent for the microwave oven?", "In 1945, after a chocolate bar melted in his pocket near a radar.", "En quelle année Percy Spencer a-t-il déposé le brevet du four à micro-ondes ?", "En 1945, après qu'une barre chocolatée a fondu dans sa poche près d'un radar.", "src: Microwave oven" },
    { 1960, "year", "In which year was the first laser built?", "In 1960, by Theodore Maiman, with a ruby crystal.", "En quelle année le premier laser a-t-il été construit ?", "En 1960, par Theodore Maiman, avec un cristal de rubis.", "src: Laser" },
    { 1947, "year", "In which year was the transistor invented at Bell Labs?", "In December 1947 — a phone today holds billions of them.", "En quelle année le transistor a-t-il été inventé aux laboratoires Bell ?", "En décembre 1947 — un téléphone en contient aujourd'hui des milliards.", "src: Transistor" },
    { 1971, "year", "In which year did Ray Tomlinson send the first e-mail between two computers?", "In 1971; he chose the @ sign.", "En quelle année Ray Tomlinson a-t-il envoyé le premier e-mail entre deux ordinateurs ?", "En 1971 ; c'est lui qui a choisi l'arobase.", "src: Ray Tomlinson; web-checked" },
    { 1973, "year", "In which year was the first call made from a handheld mobile phone?", "In April 1973, by Martin Cooper, on a 1 kg handset.", "En quelle année a eu lieu le premier appel depuis un téléphone portable ?", "En avril 1973, par Martin Cooper, avec un combiné d'un kilo.", "src: Mobile phone (Cooper 1973); web-checked" },
    { 24, "n", "How many satellites does the GPS system need, at least, to cover the whole Earth?", "24, in six orbital planes; around 30 are actually in service.", "De combien de satellites le système GPS a-t-il besoin, au minimum, pour couvrir toute la Terre ?", "24, sur six plans d'orbite ; une trentaine sont en service.", "src: GPS (US Space Force)" },
    { 1974, "year", "In which year was a barcode first scanned in a shop?", "In June 1974, in Ohio — on a pack of chewing gum.", "En quelle année un code-barres a-t-il été scanné pour la première fois en magasin ?", "En juin 1974, dans l'Ohio — sur un paquet de chewing-gum.", "src: Barcode (Marsh supermarket 1974); web-checked" },
    { 1974, "year", "In which year did Ernő Rubik invent his famous puzzle cube?", "In 1974, in Budapest, to teach 3D geometry.", "En quelle année Ernő Rubik a-t-il inventé son célèbre cube ?", "En 1974, à Budapest, pour enseigner la géométrie dans l'espace.", "src: Rubik's Cube" },
    { 1797, "year", "In which year did André-Jacques Garnerin make the first parachute jump, over Paris?", "In October 1797, from a balloon over the Parc Monceau.", "En quelle année André-Jacques Garnerin a-t-il fait le premier saut en parachute, au-dessus de Paris ?", "En octobre 1797, depuis un ballon au-dessus du parc Monceau.", "src: André-Jacques Garnerin; web-checked" },
    { 1958, "year", "In which year was the first pacemaker implanted in a patient?", "In 1958, in Sweden; the patient outlived 26 pacemakers.", "En quelle année le premier stimulateur cardiaque a-t-il été implanté ?", "En 1958, en Suède ; le patient en a usé 26.", "src: Artificial cardiac pacemaker (Larsson); web-checked" },
    { 1922, "year", "In which year was insulin first used to treat a diabetic patient?", "In January 1922, in Toronto, on 14-year-old Leonard Thompson.", "En quelle année l'insuline a-t-elle été utilisée pour la première fois chez un diabétique ?", "En janvier 1922, à Toronto, sur Leonard Thompson, 14 ans.", "src: Insulin (history)" },
    { 1959, "year", "In which year did a hovercraft first cross the English Channel?", "In July 1959 — 50 years after Blériot's flight.", "En quelle année un aéroglisseur a-t-il traversé la Manche pour la première fois ?", "En juillet 1959 — 50 ans après Blériot.", "src: SR.N1" },
    { 1930, "year", "In which year did Frank Whittle patent the jet engine?", "In 1930, aged just 22.", "En quelle année Frank Whittle a-t-il breveté le moteur à réaction ?", "En 1930, à seulement 22 ans.", "src: Frank Whittle" },
    { 1752, "year", "In which year did Benjamin Franklin fly his famous kite in a thunderstorm?", "In 1752, leading to the lightning rod.", "En quelle année Benjamin Franklin a-t-il fait voler son célèbre cerf-volant sous l'orage ?", "En 1752, ce qui mène au paratonnerre.", "src: Kite experiment" },
    { 1968, "year", "In which year was the computer mouse first shown in public?", "In December 1968, by Douglas Engelbart — it was made of wood.", "En quelle année la souris d'ordinateur a-t-elle été présentée en public ?", "En décembre 1968, par Douglas Engelbart — elle était en bois.", "src: The Mother of All Demos" },
    { 1991, "year", "In which year did the first website go online, at CERN?", "In August 1991; it explained what the Web was.", "En quelle année le premier site web a-t-il été mis en ligne, au CERN ?", "En août 1991 ; il expliquait ce qu'était le Web.", "src: CERN: the birth of the Web" },
    { 1846, "year", "In which year did Adolphe Sax patent the saxophone?", "In 1846, in Paris.", "En quelle année Adolphe Sax a-t-il breveté le saxophone ?", "En 1846, à Paris.", "src: Saxophone" },
    { 1892, "year", "In which year did Rudolf Diesel patent his engine?", "In 1892; he first meant it to run on many fuels, even peanut oil.", "En quelle année Rudolf Diesel a-t-il breveté son moteur ?", "En 1892 ; il le voulait capable de brûler toutes sortes de carburants, même l'huile d'arachide.", "src: Rudolf Diesel" },
    { 1888, "year", "In which year did John Boyd Dunlop patent the pneumatic bicycle tyre?", "In 1888, first for his son's tricycle.", "En quelle année John Boyd Dunlop a-t-il breveté le pneu à air ?", "En 1888, d'abord pour le tricycle de son fils.", "src: John Boyd Dunlop" },
    { 1876, "year", "In which year did Nikolaus Otto build his four-stroke engine?", "In 1876 — the cycle still runs most petrol cars.", "En quelle année Nikolaus Otto a-t-il construit son moteur à quatre temps ?", "En 1876 — le cycle anime encore la plupart des voitures à essence.", "src: Otto engine" },
    { 1903, "year", "In which year did Mary Anderson patent the windscreen wiper?", "In 1903; it was worked by a lever inside the car.", "En quelle année Mary Anderson a-t-elle breveté l'essuie-glace ?", "En 1903 ; il s'actionnait par un levier depuis l'habitacle.", "src: Windscreen wiper (Anderson 1903)" },
    { 1714, "year", "In which year did Daniel Fahrenheit invent the mercury thermometer?", "In 1714; his own scale came ten years later.", "En quelle année Daniel Fahrenheit a-t-il inventé le thermomètre à mercure ?", "En 1714 ; son échelle de température suit dix ans plus tard.", "src: Daniel Gabriel Fahrenheit" },
    { 1742, "year", "In which year did Anders Celsius propose his temperature scale?", "In 1742 — upside down at first: 0 for boiling water.", "En quelle année Anders Celsius a-t-il proposé son échelle de température ?", "En 1742 — à l'envers au début : 0 pour l'eau bouillante.", "src: Celsius scale (1742, inverted)" },
    { 1656, "year", "In which year did Christiaan Huygens build the first pendulum clock?", "In 1656, accurate to about a minute a day.", "En quelle année Christiaan Huygens a-t-il construit la première horloge à pendule ?", "En 1656, précise à environ une minute par jour.", "src: Pendulum clock" },
    { 1979, "year", "In which year did the first portable cassette music player go on sale?", "In 1979, in Japan.", "En quelle année le premier baladeur à cassette a-t-il été mis en vente ?", "En 1979, au Japon.", "src: Walkman (1 July 1979)" },
    { 1982, "year", "In which year did audio compact discs go on sale?", "In 1982; a CD holds about 74 minutes of music.", "En quelle année les CD audio ont-ils été commercialisés ?", "En 1982 ; un CD contient environ 74 minutes de musique.", "src: Compact disc" },
    { 74, "min", "How many minutes of music did the standard audio CD hold?", "About 74 minutes — said to fit Beethoven's Ninth.", "Combien de minutes de musique contenait le CD audio standard ?", "Environ 74 minutes — dit-on pour y loger la Neuvième de Beethoven.", "src: Compact disc (Red Book)" },
